import { colorNames, colors, type ColorSet, type RailOverrides } from '../colors';
import { publicSite } from '../public-site';
import { radius, shadow } from '../shape';
import { themeColorNames } from '../theme-colors';
import { fontFamily } from '../type';

const HEADER =
  '/* GENERATED by pnpm tokens:build — do not edit. Source: packages/tokens/src */\n' +
  '/* A school brand colour is set on <html> as --quad-brand, --quad-brand-fill, --quad-brand-fill-strong,\n   --quad-brand-strong, --quad-brand-soft, --quad-rail and --quad-rail-2 (from deriveBrand). */\n';

type Decl = [name: string, value: string];

const siteNames = Object.keys(publicSite.light) as (keyof typeof publicSite.light)[];

/** All `--quad-*` declarations for one theme. rail-active is not declared: staff falls back to the live brand at the element that uses it, so a brand set on any ancestor reaches it. */
function themeDecls(theme: 'light' | 'dark'): Decl[] {
  const set: ColorSet = colors[theme];
  const decls: Decl[] = colorNames
    .filter((name) => name !== 'rail-active')
    .map((name): Decl => {
      return [`--quad-${name}`, set[name]];
    });
  for (const name of siteNames) decls.push([`--quad-site-${name}`, publicSite[theme][name]]);
  return decls;
}

function railDecls(o: RailOverrides): Decl[] {
  return [
    ['--quad-rail', o.rail],
    ['--quad-rail-2', o['rail-2']],
    ['--quad-rail-active', o['rail-active']],
  ];
}

function block(selector: string, decls: Decl[], indent = ''): string {
  const lines = decls.map(([n, v]) => `${indent}  ${n}: ${v};`);
  return `${indent}${selector} {\n${lines.join('\n')}\n${indent}}\n`;
}

/**
 * `:root`, dark and console variable blocks (no Tailwind syntax).
 * The light and dark blocks also match any element with `data-theme`, so a container can force either theme
 * inside a page in the other one (the /design style guide shows each component in both side by side).
 */
export function buildVariableBlocks(): string {
  const light = [['color-scheme', 'light'] as Decl, ...themeDecls('light')];
  const dark = [['color-scheme', 'dark'] as Decl, ...themeDecls('dark')];
  const consoleLight = railDecls(colors.console);
  const consoleDark = railDecls(colors.consoleDark);
  const dataDark = ':root:not([data-theme="light"])';

  return [
    block(':root,\n[data-theme="light"]', light),
    block('[data-theme="dark"]', dark),
    `@media (prefers-color-scheme: dark) {\n${block(dataDark, dark, '  ')}}\n`,
    '/* Console overrides: the console has its own, darker rail. */',
    block('[data-app="console"]', consoleLight),
    block(
      '[data-theme="dark"][data-app="console"],\n[data-theme="dark"] [data-app="console"]',
      consoleDark,
    ),
    `@media (prefers-color-scheme: dark) {\n${block(
      `${dataDark}[data-app="console"],\n  ${dataDark} [data-app="console"]`,
      consoleDark,
      '  ',
    )}}\n`,
    '/* Public site accent: lime for schools, pink for parents (data-view on <html>, spec 19). */',
    block(':root', [['--quad-site-accent', `var(--quad-site-${publicSite.accent.school})`]]),
    block(':root[data-view="parent"]', [
      ['--quad-site-accent', `var(--quad-site-${publicSite.accent.parent})`],
    ]),
  ].join('\n');
}

/** Variables only, for consumers that do not use Tailwind. */
export function buildTokensCss(): string {
  return `${HEADER}\n${buildVariableBlocks()}`;
}

/** Tailwind v4 theme: utilities read the runtime `--quad-*` variables. */
export function buildThemeCss(): string {
  const colorLines = themeColorNames.map((n) =>
    n === 'rail-active'
      ? `  --color-${n}: var(--quad-rail-active, var(--quad-brand));`
      : `  --color-${n}: var(--quad-${n});`,
  );
  const radiusLines = Object.entries(radius).map(([n, v]) => `  --radius-${n}: ${v}px;`);
  const theme = [
    '@theme inline {',
    ...colorLines,
    ...radiusLines,
    `  --shadow-card: ${shadow.card};`,
    `  --shadow-lg: ${shadow.lg};`,
    `  --font-sans: ${fontFamily.sans};`,
    `  --font-accent: ${fontFamily.accent};`,
    '}\n',
  ].join('\n');
  return `${HEADER}\n${theme}\n${buildVariableBlocks()}`;
}
